import { inject } from '@angular/core';
import { Router } from '@angular/router';
import { of } from 'rxjs';
import { catchError, map, switchMap, take } from 'rxjs/operators';
import { AuthService } from './auth.service';
import { ProfileApiService } from '../profile/profile-api.service';
export const profileCompleteGuard = (_route, state) => {
  const auth = inject(AuthService);
  const api = inject(ProfileApiService);
  const router = inject(Router);
  return auth.isAuthenticated$.pipe(take(1), switchMap(isAuth => {
    if (!isAuth) return of(true);
    return api.getMe().pipe(map(me => {
      if (me.isProfileComplete) return true;
      return router.createUrlTree(['/complete-profile'], {
        queryParams: {
          returnUrl: state.url
        }
      });
    }), catchError(() => of(router.createUrlTree(['/complete-profile'], {
      queryParams: {
        returnUrl: state.url
      }
    }))));
  }));
};
